private static ThreadLocal<WebDriver> driver = new ThreadLocal<>();

@BeforeMethod
public void setup() {
    driver.set(new ChromeDriver(new ChromeOptions()));
}
@AfterMethod
public void teardown() { driver.get().quit(); }

public static WebDriver getDriver() { return driver.get(); }

